pub fn simple_nested(a: &mut Vec<i32>, b: &Vec<i32>, N: i32) -> i32 {
    // Convert N to usize for indexing
    let n = N as usize;

    // It is good to assert lengths match N for safety
    assert_eq!(a.len(), n, "Length of a must be N");
    assert_eq!(b.len(), n, "Length of b must be N");

    let mut sum = 0;
    for i in 0..n {
        // According to the problem guarantees:
        // b[i] == i or b[i] == i + 1
        // Convert i and b[i] to i32 for comparison is direct because i is usize but indexing requires usize.
        let index_i = i as i32;
        if b[i] == index_i {
            a[i] = 1;
            sum += 1;
        } else {
            // b[i] must be index_i + 1
            a[i] = 2;
            sum += 2;
        }
    }

    sum
}